    label: string;
    count?: number;
}

interface FilterSidebarProps {
    brands?: FilterOption[];
    conditions?: FilterOption[];
    priceRange?: { min: number; max: number };
    selectedFilters: {
        brand?: string;
        condition?: string;
        minPrice?: number;
        maxPrice?: number;
    };
    onFilterChange: (filters: FilterSidebarProps["selectedFilters"]) => void;
    onReset: () => void;
